	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2 })
	void coldScalarBatchNestedAndSnapshotKeepSemanticOwnerAcrossRollback(int index) throws Exception {
		Literal original = literal(index);
		Literal lower = VF.createLiteral(original.getLabel(), original.getLanguage().orElseThrow().toLowerCase(Locale.ROOT),
				original.getBaseDirection());
		TripleTerm nested = term(term(original));
		long id;
		long nestedId;
		byte[] payload;
		ValueStore values = open(true);
		try {
			id = values.storeValue(original);
			nestedId = values.storeValue(nested);
			payload = values.getData(id);
		} finally { values.close(); }
		values = open(true);
		try {
			values.clearCaches();
			assertEquals(id, values.getId(lower));
			try (ValueStore.ReadSnapshotReservation reservation = values.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start()) {
				assertEquals(id, values.getId(snapshot, lower));
				assertEquals(nestedId, values.getId(snapshot, term(term(lower))));
				assertArrayEquals(payload, values.getData(id));
			}
			values.clearCaches();
			values.startTransaction(true);
			try {
				long[] first = new long[2];
				values.storeValues(new Value[] { lower, original }, first, 2);
				assertEquals(id, first[0]);
				assertEquals(id, first[1]);
				values.clearCaches();
				long[] second = new long[1];
				values.storeValues(new Value[] { lower }, second, 1);
				assertEquals(id, second[0], "a later lexical batch shares the same existing semantic writer index");
				assertEquals(nestedId, values.storeValue(term(term(lower))));
				values.commit();
			} catch (Exception | Error failure) {
				try { values.rollback(); }
				catch (Exception | Error cleanup) { if (cleanup != failure) { failure.addSuppressed(cleanup); } }
				throw failure;
			}
			Literal temporary = VF.createLiteral("rollback raw owner", "EN");
			values.startTransaction(true);
			values.storeValues(new Value[] { temporary }, new long[1], 1);
			values.rollback();
			values.clearCaches();
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(temporary));
			assertEquals(id, values.getId(lower));
			assertEquals(nestedId, values.getId(term(term(lower))));
			assertArrayEquals(payload, values.getData(id));
		} finally { values.close(); }
		LegacyRawReverseFixture.assertRawOnly(directory.resolve("values"), id, payload);
	}

