	private static Literal literal(int index) {
		return switch (index) {
		case 0 -> VF.createLiteral("raw", "EN");
		case 1 -> VF.createLiteral("actual long raw language owner ".repeat(8), "EN-GB");
		case 2 -> VF.createLiteral("dir", "EN-GB", Literal.BaseDirection.RTL);
		default -> throw new IllegalArgumentException("literal profile " + index);
		};
	}

	/** CRC32 is linear for equal-length inputs: 33 case-flip columns already guarantee a nonzero dependency. */
	private static Literal sameHashLanguageLiteral(long datatype) {
		String label = "same hash raw owner";
		char[] lower = "en-abcdefgh-ijklmnop-qrstuvwx-yzabcdef-ghijklmn-opqrstuv-wxyzabcd-efghijkl".toCharArray();
		int[] positions = new int[64];
		int count = 0;
		for (int i = 0; i < lower.length && count < positions.length; i++) {
			if (lower[i] >= 'a' && lower[i] <= 'z') { positions[count++] = i; }
		}
		assertEquals(64, count);
		long canonical = ValueStoreRecordCodec.hash(ValueStoreRecordCodec.literalData(
				VF.createLiteral(label, new String(lower)), datatype, false));
		long[] basis = new long[32];
		long[] masks = new long[32];
		for (int i = 0; i < positions.length; i++) {
			char[] flipped = lower.clone();
			flipped[positions[i]] = Character.toUpperCase(flipped[positions[i]]);
			long column = canonical ^ ValueStoreRecordCodec.hash(ValueStoreRecordCodec.literalData(
					VF.createLiteral(label, new String(flipped)), datatype, false));
			long mask = 1L << i;
			for (int bit = 31; bit >= 0; bit--) {
				if ((column & 1L << bit) == 0L) { continue; }
				if (basis[bit] != 0L) { column ^= basis[bit]; mask ^= masks[bit]; }
				else { basis[bit] = column; masks[bit] = mask; break; }
			}
			if (column == 0L) {
				assertNotEquals(0L, mask);
				char[] upper = lower.clone();
				for (int j = 0; j < positions.length; j++) {
					if ((mask & 1L << j) != 0L) { upper[positions[j]] = Character.toUpperCase(upper[positions[j]]); }
				}
				Literal result = VF.createLiteral(label, new String(upper));
				assertNotEquals(new String(lower), result.getLanguage().orElseThrow());
				assertEquals(canonical, ValueStoreRecordCodec.hash(ValueStoreRecordCodec.literalData(result, datatype, false)));
				return result;
			}
		}
		throw new AssertionError("CRC32 columns must contain a nonzero dependency");
	}

	private static TripleTerm term(Value value) {
		return VF.createTripleTerm(VF.createIRI("urn:raw:subject"), VF.createIRI("urn:raw:predicate"), value);
	}

	private ValueStore openLegacyWithRefCountRepair() throws IOException {
		return open(true, new LmdbStoreConfig().setLegacyReferenceCountRepairEnabled(true));
	}

	private ValueStore open(boolean legacy) throws IOException {
		return open(legacy, new LmdbStoreConfig());
	}

	private ValueStore open(boolean legacy, LmdbStoreConfig config) throws IOException {
		config.setInlineLiterals(false).setValueIDCacheSize(0);
		StoreProperties properties = new StoreProperties(directory.toFile());
		if (!properties.load()) {
			if (legacy) {
				properties.setVersion("2");
				properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_CANONICAL);
			} else { LmdbStoreFormat.forNewStore(config).initializeProperties(properties); }
		}
		ValueStore store = new ValueStore(directory.resolve("values").toFile(), properties, config);
		properties.save();
		assertEquals(legacy, store.getFormat().isLegacy());
		return store;
	}
